command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="e70d3ec5c91118acd113f2d90cb6a37f1c7c4ac8";$candidate="e4c95e1c2e7c1a3ca1f3530dac86f4477c1664a3";$branch="work/unc-network-shell-visuals-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "network visual final fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before network visual final"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "network visual final candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-network-visual-final-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "network visual final worktree add failed"}
 Set-Location -LiteralPath $temp
 & git diff --check ($main+"..."+$candidate)
 if($LASTEXITCODE -ne 0){throw "network visual final diff check failed"}
 & .\build.bat Release
 if($LASTEXITCODE -ne 0){throw "network visual final Release build failed"}
 & python -u -X utf8 .\tests\winui\test_network_visual_gui.py --configuration Release --capture after --force-network-detail
 if($LASTEXITCODE -ne 0){throw "network visual final forced-network GUI failed"}
 $source=Join-Path $temp "logs\network-visual\network-visual-after.bmp"
 if(-not (Test-Path -LiteralPath $source -PathType Leaf)){throw "network visual after screenshot missing"}
 $dest=Join-Path $repo "logs\remote-evidence\network-visual-after.bmp"
 Copy-Item -LiteralPath $source -Destination $dest -Force
 Write-Host "NETWORK_VISUAL_FINAL_DIFF_CHECK=PASS"
 Write-Host "NETWORK_VISUAL_FINAL_RELEASE=PASS"
 Write-Host "NETWORK_VISUAL_FINAL_FORCED_NETWORK_GUI=PASS"
 Write-Host "NETWORK_VISUAL_AFTER_FILE=network-visual-after.bmp"
 Write-Host "NETWORK_VISUAL_PHYSICAL_SMB=NOT_RUN_NO_OWNED_SHARE"
 Write-Host "NETWORK_VISUAL_REUSED_FAST_RUN=37577331163"
 Write-Host "NETWORK_VISUAL_REUSED_BEFORE_RUN=37575384608"
}finally{
 Set-Location -LiteralPath $repo
 if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
 & git worktree prune
}
